out=[r[:] for r in grid]
rects=[(2,9,3,10),(0,9,13,24),(12,15,13,21)]
centers=[]
for r0,r1,c0,c1 in rects:
    centers += [(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1) if grid[r][c]==2]
for r,c in centers:
    for rr in range(max(0,r-1),min(len(grid),r+2)):
        for cc in range(max(0,c-1),min(len(grid[0]),c+2)):
            if grid[rr][cc] != 2: out[rr][cc]=1
centers, len(centers), '\n'.join(' '.join(map(str,r)) for r in out)
